import json
from datetime import datetime
from app.extensions import db


class ScanResult(db.Model):
    """Stores detailed assessment generated by the risk scoring engine."""

    __tablename__ = "scan_results"

    id = db.Column(db.Integer, primary_key=True)
    scan_id = db.Column(db.Integer, db.ForeignKey("scans.id", ondelete="CASCADE"), nullable=False, unique=True)
    risk_score = db.Column(db.Integer, nullable=False, index=True)  # 0 to 100
    risk_level = db.Column(db.String(30), nullable=False)  # 'Low Risk', 'Medium Risk', 'High Risk', 'Very High Risk'
    predicted_category = db.Column(db.String(100), nullable=False, index=True)
    model_version = db.Column(db.String(50), nullable=False, default="v1.0.0")
    confidence = db.Column(db.Float, nullable=False, default=0.0)
    explanation = db.Column(db.Text, nullable=False)
    recommendations = db.Column(db.Text, nullable=False)  # JSON-encoded list of safety recommendations
    created_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)

    # Relationship
    evidence_items = db.relationship("ScanEvidence", backref="scan_result", cascade="all, delete-orphan", lazy="joined")

    def get_recommendations_list(self) -> list:
        """Parse recommendations JSON string into Python list."""
        try:
            return json.loads(self.recommendations) if self.recommendations else []
        except Exception:
            return [self.recommendations] if self.recommendations else []

    def set_recommendations_list(self, recs: list) -> None:
        """Store recommendations list as JSON string."""
        self.recommendations = json.dumps(recs)

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "scan_id": self.scan_id,
            "risk_score": self.risk_score,
            "risk_level": self.risk_level,
            "predicted_category": self.predicted_category,
            "model_version": self.model_version,
            "confidence": round(self.confidence, 4),
            "explanation": self.explanation,
            "recommendations": self.get_recommendations_list(),
            "created_at": self.created_at.isoformat() if self.created_at else None,
            "evidence": [e.to_dict() for e in self.evidence_items],
        }

    def __repr__(self) -> str:
        return f"<ScanResult Scan#{self.scan_id}: {self.risk_level} ({self.risk_score}/100)>"


class ScanEvidence(db.Model):
    """Specific warnings, extracted signals, and red-flags found during scanning."""

    __tablename__ = "scan_evidence"

    id = db.Column(db.Integer, primary_key=True)
    scan_result_id = db.Column(db.Integer, db.ForeignKey("scan_results.id", ondelete="CASCADE"), nullable=False, index=True)
    evidence_type = db.Column(db.String(50), nullable=False)  # 'urgency', 'url', 'impersonation', 'financial', etc.
    evidence_description = db.Column(db.Text, nullable=False)
    severity = db.Column(db.String(20), nullable=False, default="medium", index=True)  # low, medium, high, critical

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "evidence_type": self.evidence_type,
            "evidence_description": self.evidence_description,
            "severity": self.severity,
        }

    def __repr__(self) -> str:
        return f"<ScanEvidence {self.evidence_type} [{self.severity}]>"
